params.command:
$ErrorActionPreference='Continue'
git fetch origin --prune *> $null
if($LASTEXITCODE -ne 0){throw 'fetch failed'}
$base=(git rev-parse origin/main).Trim()
$current=(git branch --show-current).Trim()
$wt=[System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach($line in (git worktree list --porcelain)){if($line -like 'branch refs/heads/*'){[void]$wt.Add($line.Substring('branch refs/heads/'.Length))}}
function PatchEq([string]$b){
 $ch=@(git cherry origin/main $b 2>$null)
 if($LASTEXITCODE -ne 0){return $false}
 return @($ch|Where-Object{$_ -like '+ *'}).Count -eq 0
}
$before=@(git for-each-ref --format='%(refname:strip=2)' refs/heads | Where-Object{$_ -and $_ -ne 'main'} | Sort-Object -Unique)
$deleted=@();$pres=@();$fail=@()
foreach($b in $before){
 if($b -eq $current){$pres+="$b :: current branch";continue}
 if($wt.Contains($b)){$pres+="$b :: checked out in worktree";continue}
 if($b -like 'release/*'){$pres+="$b :: release branch";continue}
 if($b -eq 'heaven-bridge'){$pres+="$b :: bridge infrastructure";continue}
 $ahead=[int](git rev-list --count "origin/main..$b")
 $safe=($ahead -eq 0)
 if(-not $safe){$safe=PatchEq $b}
 if($safe){
   $msg=& git branch -D "$b" 2>&1
   if($LASTEXITCODE -eq 0){$deleted+=$b}else{$fail+="$b :: $($msg -join ' | ')"}
 }else{$pres+="$b :: ahead=$ahead unique/non-equivalent"}
}
git fetch origin --prune *> $null
$after=@(git for-each-ref --format='%(refname:strip=2)' refs/heads | Sort-Object -Unique)
[ordered]@{
 origin_main_sha=$base
 current_branch=$current
 local_count_before=1+$before.Count
 deleted_local=$deleted
 preserved_local=$pres
 failures=$fail
 stale_refs_pruned=($LASTEXITCODE -eq 0)
 final_local_count=$after.Count
 final_local_branches=$after
}|ConvertTo-Json -Depth 5
